/** Scratch (measure step-back, 2026-10-31). For every labelled pair of the impact
 * pair studies (rounds 1-3) and the slam study: v3 moment strength of each judged
 * hit (strongest v3 event with onset within ±6 frames of the judged frame, the U1
 * retro rule) and a physical description of the hit and of its clip.
 * Run from the worktree root:
 *   LR_ENGINE=wasm node --import tsx <this> --out=FILE.json */
import {readFileSync, writeFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
const ROOT = process.cwd();
const {observe, songSpec, POINTS} = await import(ROOT + '/tools/measure/observe.ts');
const {strikeMotionFrames, detectStrikes, STRIKE_V3_CONTRACT} = await import(ROOT + '/tools/measure/strike.ts');
const {LineRiderEngine: Engine} = await import(ROOT + '/scripts/lib/native_motion/engine.ts');

const arg = (k: string) => process.argv.find(a => a.startsWith(`--${k}=`))?.slice(k.length + 3);
const STUDIES = ['impact-pairs-2026-10', 'impact-pairs-2026-10b', 'impact-pairs-2026-10c', 'slam-2026-10'];
const RADIUS = 6, CLIP_BEFORE = 40, CLIP_AFTER = 32;           // frames: 1.0 s before, 0.8 s after
const LIT = [-2, 4.8];                                        // light on −50 ms … +120 ms (pairs.js)
const DEG = 180 / Math.PI;
const rides = new Map<string, any>();
async function ride(set: string, song: string, seed: number) {
  const id = `${set}~${song}~${seed}`;
  if (!rides.has(id)) {
    const track = JSON.parse(gunzipSync(readFileSync(`labels/studies/sources/${id}.track.json.gz`)).toString());
    const {durationFrames, targets} = await songSpec(song), o = observe(track, durationFrames, targets);
    const frames = strikeMotionFrames(o);
    const v3 = detectStrikes(frames, STRIKE_V3_CONTRACT);
    const rest = (() => {const p = o.frames[0].points; return Math.atan2(p[2][1] - p[1][1], p[2][0] - p[1][0]);})();
    rides.set(id, {o, frames, v3, rest, targets});
    Engine.retainOnly([]);
  }
  return rides.get(id)!;
}
const vel = (o: any, f: number) => {let x = 0, y = 0; for (const [px, py, qx, qy] of o.frames[f].points) {x += px - qx; y += py - qy;} return [x / 10, y / 10];};
const spin = (o: any, f: number) => {            // angular velocity about the centre, deg/frame
  const P = o.frames[f].points; let cx = 0, cy = 0, vx = 0, vy = 0;
  for (const [x, y, px, py] of P) {cx += x; cy += y; vx += x - px; vy += y - py;}
  cx /= 10; cy /= 10; vx /= 10; vy /= 10; let L = 0, I = 0;
  for (const [x, y, px, py] of P) {const rx = x - cx, ry = y - cy; L += rx * (y - py - vy) - ry * (x - px - vx); I += rx * rx + ry * ry;}
  return L / I * DEG;
};
const pitch = (r: any, f: number) => {const p = r.o.frames[f].points; let a = Math.atan2(p[2][1] - p[1][1], p[2][0] - p[1][0]) - r.rest; a = Math.atan2(Math.sin(a), Math.cos(a)); return a * DEG;};
const ang = (a: number[], b: number[]) => Math.acos(Math.max(-1, Math.min(1, (a[0] * b[0] + a[1] * b[1]) / (Math.hypot(...a) * Math.hypot(...b) || 1)))) * DEG;

function describe(r: any, frame: number) {
  const {o, frames, v3} = r;
  const near = v3.filter((e: any) => Math.abs(e.onset - frame) <= RADIUS);
  const e = near.reduce((b: any, x: any) => (!b || x.strength > b.strength ? x : b), null);
  const clip = v3.filter((x: any) => x.onset >= frame - CLIP_BEFORE && x.onset <= frame + CLIP_AFTER)
    .map((x: any) => ({onset: x.onset, dt: x.onset - frame, kind: x.kind, s: +x.strength.toFixed(3), peak: x.peakFrame}));
  const out: any = {v3: e ? +e.strength.toFixed(4) : 0, clipEvents: clip};
  if (!e) return out;
  // strongest 2-frame window inside the event (the strength), split into travel and spin
  let best = {a: e.onset, t: 0, s: 0, n: -1};
  for (let a = e.onset; a + 1 <= e.end; a++) {
    const p = frames[a].impulse!, q = frames[a + 1].impulse!, t = Math.hypot(p[0] + q[0], p[1] + q[1]), s = Math.abs(p[2] + q[2]), n = Math.hypot(t, s);
    if (n > best.n) best = {a, t, s, n};
  }
  const before = vel(o, e.contactStart - 1), after = vel(o, Math.min(e.end + 2, o.frames.length - 1));
  let px = 0, py = 0; for (let f = e.contactStart; f <= e.end; f++) {px += frames[f].impulse![0]; py += frames[f].impulse![1];}
  const p0 = [...new Set(o.frames[e.contactStart].collisions.map(([, k]: number[]) => POINTS[k]))] as string[];
  out.bodyFirst = p0.some(p => ['BUTT', 'SHOULDER', 'RHAND', 'LHAND'].includes(p));
  out.firstFramePoints = p0.join('+');
  const pts = new Set<string>(); for (let f = e.contactStart; f <= Math.min(e.contactStart + 2, e.end); f++) for (const [, k] of o.frames[f].collisions) pts.add(POINTS[k]);
  // largest 2-frame push in the 12 frames after the event's own window, outside any event
  let late = {at: -1, n: 0};
  for (let a = e.end + 1; a + 1 <= e.end + 12 && a + 1 < frames.length; a++) {
    if (!frames[a].contact || !frames[a + 1].contact) continue;
    if (v3.some((x: any) => x !== e && x.contactStart <= a + 1 && a <= x.end)) continue;
    const p = frames[a].impulse!, q = frames[a + 1].impulse!, n = Math.hypot(p[0] + q[0], p[1] + q[1], p[2] + q[2]) / 7.55;
    if (n > late.n) late = {at: a, n};
  }
  const sb = spin(o, e.contactStart - 1), sa = spin(o, Math.min(e.end + 2, o.frames.length - 1));
  Object.assign(out, {kind: e.kind, contactStart: e.contactStart, onset: e.onset, peak: e.peakFrame, end: e.end,
    onsetMinusJudged: e.onset - frame, peakMinusJudged: e.peakFrame - frame,
    strongestWindowMinusJudged: best.a - frame, strongestWindowLit: best.a - frame >= LIT[0] && best.a + 1 - frame <= LIT[1],
    travelPart: +(best.t / 7.55).toFixed(3), spinPart: +(best.s / 7.55).toFixed(3),
    speedBefore: +Math.hypot(...before).toFixed(2), speedAfter: +Math.hypot(...after).toFixed(2), turnDeg: +ang(before, after).toFixed(1),
    netPushDir: +(Math.atan2(-py, px) * DEG).toFixed(0), // 90 = pushed straight up (floor), −90 = pushed down (roof)
    spinBefore: +sb.toFixed(1), spinAfter: +sa.toFixed(1), spinReversed: Math.sign(sb) !== Math.sign(sa) && Math.abs(sb) > 1 && Math.abs(sa) > 1,
    pitchAtContact: +pitch(r, e.contactStart).toFixed(0), firstPoints: [...pts].join('+'),
    J: frames.slice(e.contactStart - 1, e.contactStart + 11).map((f: any) => (f.contact ? '' : '.') + f.J.toFixed(1)).join(' '),
    latePush: late.at < 0 ? null : {dt: late.at - frame, s: +late.n.toFixed(3)},
    otherClipMax: Math.max(0, ...clip.filter((x: any) => Math.abs(x.dt) > RADIUS).map((x: any) => x.s))});
  return out;
}

const rows: any[] = [];
for (const study of STUDIES) {
  const key = JSON.parse(readFileSync(`labels/studies/${study}.key.json`, 'utf8')), answers = new Map<string, any>();
  for (const line of readFileSync(`labels/studies/${study}.jsonl`, 'utf8').trim().split('\n')) {const a = JSON.parse(line); answers.set(a.clip, a);} // last answer wins
  for (const p of key) {
    const a = answers.get(`pair${p.pair}`); if (!a || a.skipped) continue;
    const side = (s: 'left' | 'right') => typeof p[s] === 'object' ? p[s] : p[s] === 'body-first' ? {set: 'strike', ...p.a} : {set: 'strike', ...p.b};
    const row: any = {study, pair: p.pair, kind: p.kind, block: p.kind === 'check' ? 'check' : (p.measures ?? ['strike', 'strength']).join(' vs '),
      choice: Object.values(a.answers)[0], note: a.note || ''};
    for (const s of ['left', 'right'] as const) {
      const h = side(s), r = await ride(h.set, h.song, h.seed);
      const t = r.targets.filter((x: any) => Math.abs(x.frame - h.frame) <= 6).map((x: any) => ({dt: x.frame - h.frame, ask: x.impact}));
      row[s] = {hit: `${h.set}~${h.song}~${h.seed} f${h.frame}`, keyValues: Object.fromEntries(Object.entries(h).filter(([k, v]) => typeof v === 'number' && !['seed', 'frame', 'pair'].includes(k))),
        beatsNear: t, ...describe(r, h.frame)};
    }
    rows.push(row);
  }
}
const tail = (k: number, n: number) => {let p = 0, c = 1; for (let i = 0; i <= n; i++) {if (i >= k) p += c; c = c * (n - i) / (i + 1);} return p / 2 ** n;};
const imp = rows.filter(r => r.study !== 'slam-2026-10'), dec = imp.filter(r => r.choice === 'left' || r.choice === 'right');
const right = dec.filter(r => (r.left.v3 > r.right.v3 ? 'left' : 'right') === r.choice).length;
console.log(`impact pairs: ${imp.length}, decisive ${dec.length}, v3 right ${right}, p ${tail(right, dec.length).toFixed(5)}`);
if (arg('out')) writeFileSync(arg('out')!, JSON.stringify(rows, null, 1) + '\n');
process.exit(0);

scratchScripts.timing_grades.ts:
/** Scratch: v3 onset/peak offset vs the owner's timing and strength grades
 * (impact-2026-10), for clips whose source ride is preserved (july, current).
 * Run from the worktree root: LR_ENGINE=wasm node --import tsx <this> */
import {readFileSync, existsSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
const ROOT = process.cwd();
const {observe, songSpec} = await import(ROOT + '/tools/measure/observe.ts');
const {strikeMotionFrames, detectStrikes, accountStrikes, STRIKE_V3_CONTRACT} = await import(ROOT + '/tools/measure/strike.ts');
const {LineRiderEngine: Engine} = await import(ROOT + '/scripts/lib/native_motion/engine.ts');
const key = JSON.parse(readFileSync('labels/studies/impact-2026-10.key.json', 'utf8'));
const answers = new Map<string, any>();
for (const l of readFileSync('labels/studies/impact-2026-10.jsonl', 'utf8').trim().split('\n')) {const a = JSON.parse(l); answers.set(a.clip, a);}
const cache = new Map<string, any>();
for (const k of key) {
  const a = answers.get(k.clip); if (!a) continue;
  const path = `labels/studies/sources/${k.source}.track.json.gz`;
  if (!existsSync(path)) {console.log(JSON.stringify({clip: k.clip, source: k.source, available: false, answers: a.answers})); continue;}
  if (!cache.has(k.source)) {
    const track = JSON.parse(gunzipSync(readFileSync(path)).toString()), {durationFrames, targets} = await songSpec(k.song);
    const events = detectStrikes(strikeMotionFrames(observe(track, durationFrames, targets)), STRIKE_V3_CONTRACT);
    cache.set(k.source, {events, account: accountStrikes(events.filter((e: any) => e.onset <= durationFrames), targets, STRIKE_V3_CONTRACT), targets});
    Engine.retainOnly([]);
  }
  const {events, account, targets} = cache.get(k.source);
  const beat = targets.findIndex((t: any) => t.frame === k.frame);
  const m = account.matches.find((x: any) => x.target === beat), e = m ? events[m.event] : null;
  const near = events.filter((x: any) => Math.abs(x.onset - k.frame) <= 10).map((x: any) => `${x.onset - k.frame}:${x.strength.toFixed(2)}`);
  console.log(JSON.stringify({clip: k.clip, source: k.source, beat: k.frame, ask: k.requested, answers: a.answers, note: a.note || undefined,
    matched: !!e, v3: e ? +e.strength.toFixed(3) : null, onsetMs: e ? (e.onset - k.frame) * 25 : null, peakMs: e ? (e.peakFrame - k.frame) * 25 : null,
    contactMs: e ? (e.contactStart - k.frame) * 25 : null, eventsWithin10f: near}));
}
process.exit(0);

scratchScripts.dump.ts:
/** Scratch: per-frame dump of a preserved source ride (labels/studies/sources):
 * contact, J, 2-frame whole-body change (÷7.55), contacted points, v3 events.
 *   LR_ENGINE=wasm node --import tsx <this> --source=<set>~<song>~<seed> --from=F --to=F */
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
const ROOT = process.cwd();
const {observe, songSpec, POINTS} = await import(ROOT + '/tools/measure/observe.ts');
const {strikeMotionFrames, detectStrikes, STRIKE_V3_CONTRACT} = await import(ROOT + '/tools/measure/strike.ts');
const arg = (k: string) => process.argv.find(a => a.startsWith(`--${k}=`))?.slice(k.length + 3)!;
const [set, song, seed] = arg('source').split('~'), from = +arg('from'), to = +arg('to');
const track = JSON.parse(gunzipSync(readFileSync(`labels/studies/sources/${set}~${song}~${seed}.track.json.gz`)).toString());
const {durationFrames, targets} = await songSpec(song), o = observe(track, durationFrames, targets);
const frames = strikeMotionFrames(o), v3 = detectStrikes(frames, STRIKE_V3_CONTRACT);
for (let f = from; f <= to; f++) {
  const x = frames[f], p = x.impulse!, q = frames[f + 1]?.impulse ?? [0, 0, 0];
  const two = Math.hypot(p[0] + q[0], p[1] + q[1], p[2] + q[2]) / 7.55;
  const e = v3.find((e: any) => e.contactStart <= f && f <= e.end), beat = targets.find((t: any) => t.frame === f);
  const pts = [...new Set(o.frames[f].collisions.map(([, k]: number[]) => POINTS[k]))].join('+');
  console.log(`${f} ${(f / 40).toFixed(3)} ${x.contact ? 'C' : '.'} J ${x.J.toFixed(2)} 2f ${two.toFixed(2)} push(${p[0].toFixed(2)},${p[1].toFixed(2)}) spin ${p[2].toFixed(2)} ${e ? `v3[${e.contactStart}..${e.end}]${e.onset === f ? ' ONSET ' + e.strength.toFixed(3) : ''}` : ''} ${beat ? 'BEAT ask ' + beat.impact : ''} ${pts}`);
}
process.exit(0);

