import math
def wilson(k, n, z=1.96):
    p = k / n; d = 1 + z * z / n; c = (p + z * z / (2 * n)) / d; h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return round(c - h, 2), round(c + h, 2)
def tail(k, n):
    return sum(math.comb(n, i) for i in range(k, n + 1)) / 2 ** n
for k, n, what in [(47, 63, 'v3 all decisive'), (20, 23, 'v3 strike-vs-strength block'), (9, 10, 'checks'), (18, 30, 'v3 in blocks vs close candidates (whole, travel, c_arrive_spin x2)'),
                   (17, 28, 'v3 ratio<1.5'), (30, 35, 'v3 ratio>=1.5'), (4, 9, 'cluttered preferred (nearest rule)'), (45, 54, 'not cluttered (nearest rule)'),
                   (15, 24, 'v3 round 3')]:
    print(what, f'{k}/{n}', wilson(k, n), 'one-sided sign p', round(tail(k, n), 4))
# power of a 16-pair block (assume ~14 decisive) at rule >= 11/14
for n, thr in [(14, 11), (16, 12), (12, 10)]:
    for p in (.5, .7, .8):
        pw = sum(math.comb(n, i) * p ** i * (1 - p) ** (n - i) for i in range(thr, n + 1))
        print(f'n={n} rule>={thr}: P(pass | p={p}) = {pw:.3f}')
# detection bins: 6 per bin, visible if chosen >= 5/6
for p in (.1, .5, .8, .9):
    print('bin of 6, P(>=5 chosen | p=%.1f) = %.3f' % (p, sum(math.comb(6, i) * p ** i * (1 - p) ** (6 - i) for i in (5, 6))),
          ' P(<=1 chosen) = %.3f' % sum(math.comb(6, i) * p ** i * (1 - p) ** (6 - i) for i in (0, 1)))
